from pathlib import Path
p=Path('app/dashboard.tsx');s=p.read_text(encoding='utf-8-sig')
needle=" const t=state?.tournaments.find"
insert=''' useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'read_alliance_tournaments',title:'Read Alliance tournaments',description:'Read tournament names, formats and match completion counts from the current shared workspace.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input:any){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return {tournaments:ref.current?.tournaments.map(t=>({id:t.id,name:t.name,mode:t.mode,teams:t.teamIds.length,matches:t.games.length,completed:t.games.filter(g=>g.status==='final').length}))??[]};}},{name:'open_alliance_match',title:'Open a match score desk',description:'Navigate to the score desk for an existing match without changing scores or results.',inputSchema:{type:'object',properties:{tournamentId:{type:'string'},matchId:{type:'string'}},required:['tournamentId','matchId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input:any){if(!input||typeof input.tournamentId!=='string'||typeof input.matchId!=='string'||Object.keys(input).some(k=>!['tournamentId','matchId'].includes(k)))throw Error('A tournament ID and match ID are required.');const tour=ref.current?.tournaments.find(t=>t.id===input.tournamentId);if(!tour?.games.some(g=>g.id===input.matchId))throw Error('Match not found.');setSelected(tour.id);setSelectedGame(input.matchId);go('scoreboard');return {opened:true,tournamentId:tour.id,matchId:input.matchId};}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}return()=>lifecycle.abort();},[]);
'''
s=s.replace(needle,insert+needle);p.write_text(s,encoding='utf-8')
p=Path('app/reports-page.tsx');s=p.read_text(encoding='utf-8-sig');s=s.replace('<article className="report-sheet" id="report-sheet">','{state.tournaments.some(tour=>tour.games.some(g=>g.id===r.matchId&&(g.status!==\'final\'||JSON.stringify(g.events)!==JSON.stringify(r.game.events))))&&<p className="error-banner">This saved snapshot predates changes to the match. Finalize the match again to refresh its report.</p>}<article className="report-sheet" id="report-sheet">');p.write_text(s,encoding='utf-8')
